#!/usr/bin/env python3
"""Writes scripts/status/consts.luau from the constants dump of the patched legacy binary (RA_GOLDEN_ST_DUMP), so that no enum value used by
a status definition (RINGNBL_*, SL_HIGH, BREAK_*, BCT_*, MD_*, ELE_*, ...) is typed in by hand.

usage: gen_status_consts.py <dump.txt> <out consts.luau>
"""
import pathlib, sys

dump = pathlib.Path(sys.argv[1]).read_text().splitlines()
consts = [l.split() for l in dump if l.startswith("const ")]
out = ["--!nonstrict",
       "-- GENERATED by conformance/golden_gen/gen_status_consts.py from the constants dump of the patched RENEWAL legacy binary. Do not edit.",
       "-- The values the expression language of the status definitions resolves identifiers against (scripts/status/expr.luau).",
       "return {"]
for _, name, val in consts:
    out.append(f"\t{name} = {val},")
out.append("}")
pathlib.Path(sys.argv[2]).write_text("\n".join(out) + "\n")
print(f"{len(consts)} constants")
